property.value:

//VariableDeclarationStatements[
	VariableDeclaration/VariableExpression
	and (
		let $varDecl := VariableDeclaration,
			$varName := $varDecl/VariableExpression/@Image,
			$method := ancestor::Method[1]
		return
			not(some $ve in $method//ReturnStatement//VariableExpression[@Image = $varName] satisfies not(ancestor::VariableDeclaration[1] = $varDecl))
			and not(some $ve in $method//MethodCallExpression//VariableExpression[@Image = $varName] satisfies not(ancestor::VariableDeclaration[1] = $varDecl))
			and not(some $ve in $method//NewObjectExpression//VariableExpression[@Image = $varName] satisfies not(ancestor::VariableDeclaration[1] = $varDecl))
			and not(some $ve in $method//NewKeyValueObjectExpression//AssignmentExpression/VariableExpression[position() > 1][@Image = $varName] satisfies not(ancestor::VariableDeclaration[1] = $varDecl))
	)
]

rule.example:

// Violation: Variable assigned but not used
public void method1() {
	String unused = 'test';
	// Variable is never returned or passed
}

// Valid: Variable returned
public String method2() {
	String result = 'test';
	return result;
}

// Valid: Variable passed to method
public void method3() {
	String value = 'test';
	process(value);
}

// Valid: Variable passed to constructor
public void method4() {
	String name = 'Test';
	Account acc = new Account(Name = name);
}


// Violation: Variable assigned after being used but not returned or passed
public void method5() {
	String value = 'test';
	process(value);
	value = 'test2'; // ❌ Variable is assigned but not used
}

// Violation: Variable incremented but not returned or passed
public void method6() {
	Integer value = 0;
	process(value);
	value++; // ❌ Variable incremented but not returned or passed
}

// Violation: Variable decremented but not returned or passed
public void method7() {
	Integer value = 0;
	process(value);
	value--; // ❌ Variable decremented but not returned or passed
}


// Violation: Variable assigned but not returned or passed (after being used in constructor)
public void method8() {
	String value = 'test';
	Account acc = new Account(Name = value);
	value = 'test2'; // ❌ Variable used in constructor is assigned but not returned or passed
}

// Violation: Variable incremented but not returned or passed (after being used in constructor)
public void method9() {
	Integer value = 0;
	Account acc = new Account(NumberOfEmployees = value);
	value++; // ❌ Variable used in constructor is incremented but not returned or passed
}

// Violation: Variable decremented but not returned or passed (after being used in constructor)
public void method10() {
	Integer value = 0;
	Account acc = new Account(NumberOfEmployees = value);
	value--; // ❌ Variable used in constructor is decremented but not returned or passed
}
